// Oeste Lede — Huntington theme (v0.2.0).
// Copy-paste ready. Requires: React 18+, Tailwind with arbitrary values, JSX transform.
// Requires Huntington tokens: import src/tokens.css once (or copy src/tokens.json).
// Source: https://github.com/eric2busy/Oeste/blob/main/huntington/src/index.js
// Docs: https://oeste.hiddeninwest.com/huntington/#/components/lede

export function Lede({ children }) {
  return (
    <p className="m-0 max-w-[572px] text-[var(--type-lede-size)] leading-[var(--type-lede-leading)] tracking-[var(--type-lede-tracking)] text-[var(--color-ink)] [font-weight:var(--type-lede-weight)]">{children}</p>
  );
}
